public class InnerGatewayRuleConfigurationBundleActionFactory(Action<Humidifier.BedrockAgentCore.GatewayRuleTypes.ConfigurationBundleAction> factoryAction = null) : SubResourceFactory<Humidifier.BedrockAgentCore.GatewayRuleTypes.ConfigurationBundleAction>
{

    internal InnerGatewayRuleStaticOverrideFactory StaticOverrideFactory { get; set; }

    internal InnerGatewayRuleWeightedOverrideFactory WeightedOverrideFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.GatewayRuleTypes.ConfigurationBundleAction Create()
    {
        var configurationBundleActionResult = CreateConfigurationBundleAction();
        factoryAction?.Invoke(configurationBundleActionResult);

        return configurationBundleActionResult;
    }

    private Humidifier.BedrockAgentCore.GatewayRuleTypes.ConfigurationBundleAction CreateConfigurationBundleAction()
    {
        var configurationBundleActionResult = new Humidifier.BedrockAgentCore.GatewayRuleTypes.ConfigurationBundleAction();

        return configurationBundleActionResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.GatewayRuleTypes.ConfigurationBundleAction result)
    {
        base.CreateChildren(result);

        result.StaticOverride ??= StaticOverrideFactory?.Build();
        result.WeightedOverride ??= WeightedOverrideFactory?.Build();
    }

} // End Of Class

